function maxLength(nums) {
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  // Every lcm divides lcm(1..10) = 2520 and every gcd is at most 10.
  const limit = 2520 * 10;
  let best = 0;
  for (let left = 0; left < nums.length; left++) {
    let product = 1;
    let curGcd = 0;
    let curLcm = 1;
    for (let right = left; right < nums.length; right++) {
      product *= nums[right];
      if (product > limit) {
        break;
      }
      curGcd = gcd(curGcd, nums[right]);
      curLcm = (curLcm / gcd(curLcm, nums[right])) * nums[right];
      if (product === curLcm * curGcd) {
        best = Math.max(best, right - left + 1);
      }
    }
  }
  return best;
}

