function maxLength(nums) {
  // Test the definition on every subarray, recomputing product, gcd and lcm from scratch each time.
  const gcd = (a, b) => { while (b !== 0) [a, b] = [b, a % b]; return a; };
  let best = 0;
  for (let i = 0; i < nums.length; i++)
    for (let j = i; j < nums.length; j++) {
      const part = nums.slice(i, j + 1);
      const prod = part.reduce((p, v) => p * v, 1);
      const g = part.reduce(gcd, 0);
      const l = part.reduce((m, v) => (m * v) / gcd(m, v), 1);
      if (prod === l * g) best = Math.max(best, part.length);
    }
  return best;
}

