function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const n = size === 'large' ? 100 : 2 + pick(9);
  // Ones are coprime to everything, so their share decides how long the answer can grow.
  const ones = [0, 0.3, 0.6, 0.9][pick(4)];
  const top = size === 'large' ? 10 : [2, 4, 10][pick(3)];
  return [Array.from({ length: n }, () => (rand() < ones ? 1 : 1 + pick(top)))];
}
